// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(bytes32 assertionId) public {
        // The reference C allows assertionDisputedCallback to be called by the optimistic asserter (address(this)).
        // The mutant reverts because msg.sender == address(0) is false.
        bool reverted = false;
        try c.assertionDisputedCallback(assertionId) {
            // call succeeded
        } catch {
            reverted = true;
        }
        assertTrue(!reverted, "assertionDisputedCallback should not revert when called by the optimistic asserter");
    }
}

